<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('project_risks.view');$pdo=db();$projectId=(int)($_GET['project_id']??0);$project=$projectId?pm_fetch_project($pdo,$projectId):null;$projects=pm_project_options($pdo);$where=$projectId?'WHERE r.project_id=?':'';$s=$pdo->prepare("SELECT r.*,p.name project_name,u.name owner_name,(r.probability*r.impact) score FROM project_risks r JOIN projects p ON p.id=r.project_id LEFT JOIN users u ON u.id=r.owner_user_id $where ORDER BY FIELD(r.status,'open','mitigating','accepted','closed'),score DESC,r.due_date");$s->execute($projectId?[$projectId]:[]);$rows=$s->fetchAll();$open=array_filter($rows,fn($r)=>in_array($r['status'],['open','mitigating'],true));$critical=count(array_filter($open,fn($r)=>(int)$r['score']>=6400));$warning=count(array_filter($open,fn($r)=>(int)$r['score']>=3600&&(int)$r['score']<6400));$mitigating=count(array_filter($rows,fn($r)=>$r['status']==='mitigating'));$pageTitle='Riesgos de proyectos';require __DIR__.'/includes/header.php';if($project)echo pm_project_tabs($projectId,'risks');?>
<div class="project-hero compact"><div><span class="eyebrow">GESTIÓN DE RIESGOS</span><h2>Registro y seguimiento de riesgos</h2><p>Identifica amenazas, prioriza por probabilidad × impacto y deja visible quién debe mitigarlas.</p></div><div class="actions"><?php if(has_permission('project_risks.manage')):?><a class="btn btn-primary" href="project_risk_form.php<?=$projectId?'?project_id='.$projectId:''?>">+ NUEVO RIESGO</a><?php endif;?><form method="get"><select name="project_id" onchange="this.form.submit()"><option value="0">Todos los proyectos</option><?php foreach($projects as$p):?><option value="<?=$p['id']?>" <?=$projectId===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></form></div></div><div class="risk-overview"><div class="risk-kpi critical"><small>Críticos</small><strong><?=$critical?></strong><span>Actuar ahora</span></div><div class="risk-kpi warning"><small>En observación</small><strong><?=$warning?></strong><span>Requieren seguimiento</span></div><div class="risk-kpi"><small>Activos</small><strong><?=count($open)?></strong><span>Abiertos + mitigación</span></div><div class="risk-kpi ok"><small>Mitigándose</small><strong><?=$mitigating?></strong><span>Acción en curso</span></div></div><section class="panel"><div class="panel-header"><div><h2>Matriz operativa</h2><span class="table-sub">Rojo = crítico, amarillo = atención, verde = controlado.</span></div></div><div class="panel-body"><div class="risk-card-list"><?php if(!$rows):?><div class="empty">No hay riesgos registrados.</div><?php endif;?><?php foreach($rows as$r):$score=(int)$r['score'];$level=$score>=6400?'critical':($score>=3600?'warning':'ok');?><div class="risk-row-card <?=$level?>"><div><a class="table-title" href="project_risk_form.php?id=<?=$r['id']?>"><?=e($r['title'])?></a><small class="table-sub"><?=e($r['category']?:'General')?> · <?=e($r['project_name'])?></small></div><div><small class="table-sub">Responsable</small><strong><?=e($r['owner_name']?:'Sin asignar')?></strong></div><div><small class="table-sub">Prob.</small><strong><?=(int)$r['probability']?>%</strong></div><div><small class="table-sub">Impacto</small><strong><?=(int)$r['impact']?>%</strong></div><div><span class="risk-level <?=$level?>"><?=$level==='critical'?'CRÍTICO':($level==='warning'?'ATENCIÓN':'CONTROLADO')?> · <?=$score?></span></div><div><small class="table-sub">Objetivo</small><strong><?=e(pm_date($r['due_date']))?></strong><small class="table-sub"><?=e(ucfirst($r['status']))?></small></div></div><?php endforeach;?></div></div></section><?php require __DIR__.'/includes/footer.php';?>
